// Exercise Rml::MakeMoveIterator by moving a range of strings from one container to another.
// Requirements enforced: valid iterators over a live range, use only while range is valid.

// Generate a small vector of strings to operate on.
size_t n = (size_t)(*FUZZ_PARAM(unsigned int) % 8u) + 1u; // [1, 8]
std::vector<Rml::String> src;
src.reserve(n);
for (size_t i = 0; i < n; ++i) {
    std::string s = FUZZ_PARAM_STR();
    src.emplace_back(s);
}

// Create move-iterators for the full range using the target function.
auto it_begin = Rml::MakeMoveIterator(src.begin());
auto it_end   = Rml::MakeMoveIterator(src.end());

// Move-insert the entire range into a destination container.
std::vector<Rml::String> dst;
dst.insert(dst.end(), it_begin, it_end);

// Basic property: container sizes should match after moving.
FUZZ_ASSERT(src.size() == dst.size(), "Move range should preserve element count");

// Also try moving a single element at a random valid position to cover single-iterator dereference.
size_t idx = (n == 0) ? 0 : ((size_t)*FUZZ_PARAM(unsigned int) % n);
auto single_it = Rml::MakeMoveIterator(src.begin() + (std::ptrdiff_t)idx);
std::vector<Rml::String> single_dst;
single_dst.emplace_back(*single_it); // dereference yields an rvalue-reference

